const data = $json;

const requiredFields = [
  "Product Name",
  "Product ID",
  "Our Price",
  "Competitor Name",
  "Competitor Price",
  "Check Date"
];

const missingFields = requiredFields.filter(
  field =>
    data[field] === undefined ||
    data[field] === null ||
    data[field] === ""
);

const pricesValid =
  Number(data["Our Price"]) >= 0 &&
  Number(data["Competitor Price"]) >= 0;

return {
  json: {
    ...data,
    data_valid: missingFields.length === 0 && pricesValid,
    missing_fields: missingFields
  }
};

const data = $json;

const ourPrice = Number(data["Our Price"]);
const competitorPrice = Number(data["Competitor Price"]);

const difference = ourPrice - competitorPrice;

const percentageDifference =
  competitorPrice !== 0
    ? (difference / competitorPrice) * 100
    : 0;

let pricePosition;

if (ourPrice < competitorPrice) {
  pricePosition = "Cheaper Than Competitor";
} else if (ourPrice > competitorPrice) {
  pricePosition = "More Expensive Than Competitor";
} else {
  pricePosition = "Same Price";
}

return {
  json: {
    ...data,
    price_difference: Number(difference.toFixed(2)),
    percentage_difference: Number(percentageDifference.toFixed(2)),
    price_position: pricePosition
  }
};

